var i=`1272-fungee-and-pepperpot`;var t=`world-1272`;var a=`AG`;var r=`central-america-caribbean`;var o=4;var s=129;var m={en:`Fungee and Pepperpot`,ua:`Фунджі та пеперпот`};var g={en:`Fungee and Pepperpot is a dish from Antigua and Barbuda featuring beef chuck, yellow onion, okra, pumpkin. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Фунджі та пеперпот, страва кухні країни Антигуа і Барбуда з такими основними складниками: яловича лопатка, жовта цибуля, бамія, гарбуз. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 65 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 65 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:65,i:[[`beef-chuck`,620,`g`],[`water`,1100,`ml`],[`yellow-onion`,150,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 38 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 38 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:38,i:[[`okra`,280,`g`],[`pumpkin`,320,`g`],[`eggplant`,260,`g`],[`tomato`,290,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`cornmeal`,340,`g`],[`water`,650,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 14 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 14 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:14,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`hot-sauce`,35,`ml`]]}];var d={slug:i,id:t,country:`AG`,region:r,servings:4,minutes:129,title:m,text:g,steps:l};export{a as country,d as default,t as id,s as minutes,r as region,o as servings,i as slug,l as steps,g as text,m as title};